sys_script_include.script:
var VendorUtils = Class.create();
VendorUtils.prototype = {
    initialize: function() {
    },
	 // 1. Fetch vendor details by ID
    getVendorDetailsById: function (vendorId) {
        var gr = new GlideRecord('x_1790229_event_ma_vendor');
        gr.addQuery('number', vendorId);
        gr.query();

        while (gr.next()) {
            return 'Name: ' + gr.getValue('u_vendor_name') +
                ', Service: ' + gr.getValue('u_service_provider') +
                ', Contact: ' + gr.getValue('u_contact_number') +
                ', Email: ' + gr.getValue('u_email');
        }
        return 'Vendor not found';
    },

    // 2. Check if a vendor is available (true/false field)
    isVendorAvailable: function (vendorId) {
        var gr = new GlideRecord('x_1790229_event_ma_vendor');
        gr.addQuery('number', vendorId);
        gr.query();

        while (gr.next()) {
            return gr.getValue('u_available') == 'true' ? 'vendor is available' : 'vendor is not available';
        }
        return 'false';
    },

    // 3. Fetch vendors by event ID
    getVendorsByEventId: function (eventId) {
        var gr = new GlideRecord('x_1790229_event_ma_vendor');
        gr.addQuery('u_event_id.number', eventId);
        gr.query();

        var result = [];
        while (gr.next()) {
            result.push(
                'Vendor: ' + gr.getValue('u_vendor_name') +
                ', Service: ' + gr.getValue('u_service_type') +
                ', Contact: ' + gr.getValue('u_contact_number')
            );
        }
        return result.length ? result.join('\n') : 'No vendors found for this event';
    },


    type: 'VendorUtils'
};
